<script>import{adminApi}from"../../services/adminApi";import Swal from"sweetalert2";const blank=()=>({name:"",description:"",monthlyFee:0,defaultTakeRatePercent:5,maxShowsPerMonth:0,maxPhotosCount:0,maxVideosCount:0,maxDesignerAssets:10,maxDesignerPosters:10,durationMonths:12,isActive:true});export default{data(){return{items:[],loading:true,editing:null,modalOpen:false,form:blank()}},async mounted(){this.cleanupModal();await this.load()},beforeUnmount(){this.cleanupModal()},methods:{cleanupModal(){document.querySelectorAll(".modal-backdrop").forEach(el=>el.remove());document.body.classList.remove("modal-open");document.body.style.removeProperty("overflow");document.body.style.removeProperty("padding-right")},money(v){return Number(v||0).toLocaleString("pt-BR",{style:"currency",currency:"BRL"})},async load(){this.loading=true;try{this.items=await adminApi.plans()}finally{this.loading=false}},newPlan(){this.editing=null;this.form=blank();this.modalOpen=true},edit(x){this.editing=x.id;this.form={...blank(),...x};this.modalOpen=true},async save(){try{if(!this.form.name.trim())return Swal.fire("Atenção","Informe o nome do plano.","warning");if(this.editing)await adminApi.updatePlan(this.editing,this.form);else await adminApi.createPlan(this.form);await Swal.fire("Pronto","Plano salvo com sucesso.","success");this.modalOpen=false;this.cleanupModal();await this.load()}catch(e){Swal.fire("Erro",e.response?.data||"Não foi possível salvar o plano.","error")}}}}</script><template><div><div class="d-flex justify-content-between align-items-center mb-3"><div><h4>Planos SaaS</h4><p class="text-muted mb-0">CRUD conectado aos endpoints já existentes.</p></div><button class="btn btn-primary" @click="newPlan"><i class="ri-add-line me-1"></i>Novo plano</button></div><div class="row"><div v-for="x in items" :key="x.id" class="col-xl-4 col-md-6"><div class="card h-100"><div class="card-body"><div class="d-flex justify-content-between"><h5>{{x.name}}</h5><span class="badge" :class="x.isActive?'bg-success-subtle text-success':'bg-secondary-subtle text-secondary'">{{x.isActive?'Ativo':'Inativo'}}</span></div><h3>{{money(x.monthlyFee)}}<small class="fs-13 text-muted"> / período</small></h3><p class="text-muted">{{x.description}}</p><div class="small"><div>Take rate: <strong>{{x.defaultTakeRatePercent}}%</strong></div><div>Shows/mês: <strong>{{x.maxShowsPerMonth}}</strong></div><div>Fotos: {{x.maxPhotosCount}} · Vídeos: {{x.maxVideosCount}}</div><div>Designer: {{x.maxDesignerAssets}} assets</div></div></div><div class="card-footer"><button class="btn btn-sm btn-outline-primary w-100" @click="edit(x)">Editar plano</button></div></div></div></div><div v-if="modalOpen" class="modal show" id="planModal" tabindex="-1" style="display:block" @click.self="modalOpen=false"><div class="modal-dialog modal-lg"><div class="modal-content"><div class="modal-header"><h5 class="modal-title">{{editing?'Editar':'Novo'}} plano</h5><button class="btn-close" @click="modalOpen=false"></button></div><div class="modal-body"><div class="row g-3"><div class="col-md-8"><label class="form-label">Nome</label><input v-model="form.name" class="form-control"></div><div class="col-md-4"><label class="form-label">Mensalidade</label><input v-model.number="form.monthlyFee" type="number" step="0.01" class="form-control"></div><div class="col-12"><label class="form-label">Descrição</label><textarea v-model="form.description" class="form-control"></textarea></div><div class="col-md-4"><label class="form-label">Take rate %</label><input v-model.number="form.defaultTakeRatePercent" type="number" class="form-control"></div><div class="col-md-4"><label class="form-label">Shows/mês</label><input v-model.number="form.maxShowsPerMonth" type="number" class="form-control"></div><div class="col-md-4"><label class="form-label">Duração (meses)</label><input v-model.number="form.durationMonths" type="number" class="form-control"></div><div class="col-md-4"><label class="form-label">Fotos</label><input v-model.number="form.maxPhotosCount" type="number" class="form-control"></div><div class="col-md-4"><label class="form-label">Vídeos</label><input v-model.number="form.maxVideosCount" type="number" class="form-control"></div><div class="col-md-4"><label class="form-label">Assets Designer</label><input v-model.number="form.maxDesignerAssets" type="number" class="form-control"></div><div class="col-12 form-check ms-2"><input v-model="form.isActive" type="checkbox" class="form-check-input" id="activePlan"><label for="activePlan" class="form-check-label">Plano ativo</label></div></div></div><div class="modal-footer"><button class="btn btn-light" @click="modalOpen=false">Cancelar</button><button class="btn btn-primary" @click="save">Salvar plano</button></div></div></div></div><div v-if="modalOpen" class="modal-backdrop fade show"></div></div></template>